import { sketchGeometryProofHandlers } from "./sketch-geometry-proof-manifest.js";

/** Route spellings generated by the shared catalog's existing CLI/MCP projections. */
export const sketchGeometryProofPublicRoutes = Object.freeze(
  sketchGeometryProofHandlers.map((operation) =>
    Object.freeze({
      operation,
      catalogPath: "src/catalog/sketch-geometry-proof.json",
      cli: operation.replace(".", " "),
      mcp: `fmcad_cad_${operation.replaceAll(".", "_").replaceAll("-", "_")}`,
      requiresDocument: true,
      readOnlyRequested: true,
    }),
  ),
);
